const d=typeof input.d==='string'?JSON.parse(input.d):input.d;
const deny=new Set((d||[]).map(x=>{let s=String(x.id||x.phone||'').replace(/\D/g,'');if(s.startsWith('972'))s='0'+s.slice(3);return s;}));
let rows=[];try{rows=JSON.parse(input.data)}catch(e){rows=[]}
const all=[];const seen=new Set();let blocked=0;
for(const r of rows){let p=String(r.p||'').replace(/\D/g,'');if(p.startsWith('972'))p='0'+p.slice(3);if(p.length===9)p='0'+p;
if(!/^05\d{8}$/.test(p)||seen.has(p))continue;seen.add(p);if(deny.has(p)){blocked++;continue;}
const nm=String(r.n||'').trim().split(/\s+/);
all.push({phone:p,firstName:nm[0]||'',lastName:nm.slice(1).join(' '),audience:input.aud,notes:String(r.note||'').slice(0,480),customLeadFields:{}});}
const batches=[];for(let i=0;i<all.length;i+=200)batches.push({customers:all.slice(i,i+200),idx:batches.length+1,n:Math.min(200,all.length-i)});
return {batches,total:all.length,blocked,denySize:deny.size};
